  const tabOrder = ['resumo','ano','performance','historico','receitas','abanca','pessoais','credito','sara','invest','portfolio','transacoes','calendario','agenda','extrato'];
  
  useEffect(() => {
    const handleKeyDown = (e) => {
      // Ignorar se estiver a escrever num input - verificar tanto target como activeElement
      const target = e.target;
      const activeEl = document.activeElement;
      
      const isInput = (el) => el && (
        el.tagName === 'INPUT' || 
        el.tagName === 'TEXTAREA' || 
        el.tagName === 'SELECT' ||
        el.isContentEditable ||
        el.closest('input, textarea, select, [contenteditable="true"]')
      );
      
      // Alt+← / Alt+→ mudam o mês em qualquer sítio (também a escrever) — e não deixam o browser recuar
      if ((e.key === 'ArrowLeft' || e.key === 'ArrowRight') && e.altKey && !e.ctrlKey && !e.metaKey) {
        e.preventDefault();
        const idx = meses.indexOf(mes);
        if (e.key === 'ArrowLeft') { if (idx > 0) setMes(meses[idx - 1]); else { setMes(meses[11]); setAno(a => a - 1); } }
        else if (idx < 11) setMes(meses[idx + 1]); else { setMes(meses[0]); setAno(a => a + 1); }
        return;
      }
      if (isInput(target) || isInput(activeEl)) {
        // Só permitir Escape para sair do input
        if (e.key === 'Escape') {
          activeEl?.blur();
        }
        // Não fazer mais nada - deixar o input funcionar normalmente
        return;
      }
      
      // Ctrl+Z = Undo
      if (e.ctrlKey && e.key === 'z' && !e.shiftKey) {
        e.preventDefault();
        handleUndo?.();
      }
      // Ctrl+Shift+Z ou Ctrl+Y = Redo
      if ((e.ctrlKey && e.shiftKey && e.key === 'z') || (e.ctrlKey && e.key === 'y')) {
        e.preventDefault();
        handleRedo?.();
      }
      // Ctrl+F = Pesquisa
      if (e.ctrlKey && e.key === 'f') {
        e.preventDefault();
        if (tabRef.current === 'trabalho') { abrirCriativos(); return; }
        setShowSearch(true);
      }
      // Ctrl+K = Procurar nos criativos (Trabalho › Criativos)
      if ((e.ctrlKey || e.metaKey) && !e.shiftKey && (e.key === 'k' || e.key === 'K')) {
        e.preventDefault();
        try { localStorage.setItem('trab-sel', JSON.stringify({ tipo: 'criativos' })); localStorage.setItem('criativos-foco', '1'); } catch (err) { /* sem armazenamento */ }
        window.dispatchEvent(new Event('trab-criativos'));
        setTab('trabalho');
        return;
      }
      // Ctrl+P = Exportar PDF
      if (e.ctrlKey && e.key === 'p') {
        e.preventDefault();
        exportToPDF?.();
      }
      // ? = Mostrar atalhos
      if (e.key === '?') {
        e.preventDefault();
        setShowShortcuts(s => !s);
      }
      // 1-9 = Navegar entre tabs
      if (e.key >= '1' && e.key <= '9' && !e.ctrlKey && !e.altKey) {
        const idx = parseInt(e.key) - 1;
        if (idx < tabOrder.length) {
          e.preventDefault();
          setTab(tabOrder[idx]);
        }
      }
      // 0 = Última tab (Agenda)
      if (e.key === '0' && !e.ctrlKey && !e.altKey) {
        e.preventDefault();
        setTab('agenda');
      }
      // Ctrl+. = Esconder/mostrar os valores
      if (e.ctrlKey && e.key === '.') { e.preventDefault(); setPrivado(v => !v); return; }
      // Ctrl+← Ctrl+→ = Menu principal anterior/seguinte
      if ((e.key === 'ArrowLeft' || e.key === 'ArrowRight') && e.ctrlKey && !e.shiftKey && !e.altKey) { e.preventDefault(); if (menuNavRef.current) menuNavRef.current(e.key === 'ArrowLeft' ? -1 : 1); return; }
      // ← → = Recuar / avançar (para onde estavas)
      if (e.key === 'ArrowLeft' && !e.ctrlKey && !e.shiftKey && !e.altKey && !e.metaKey) { e.preventDefault(); recuar(); return; }
      if (e.key === 'ArrowRight' && !e.ctrlKey && !e.shiftKey && !e.altKey && !e.metaKey) { e.preventDefault(); avancar(); return; }
      // Shift+← Shift+→ = Mês anterior/seguinte (o Alt é tratado lá em cima)
      if (e.key === 'ArrowLeft' && e.shiftKey && !e.ctrlKey) {
        e.preventDefault();
        const idx = meses.indexOf(mes);
        if (idx > 0) setMes(meses[idx - 1]);
        else { setMes(meses[11]); setAno(a => a - 1); }
      }
      if (e.key === 'ArrowRight' && e.shiftKey && !e.ctrlKey) {
        e.preventDefault();
        const idx = meses.indexOf(mes);
        if (idx < 11) setMes(meses[idx + 1]);
        else { setMes(meses[0]); setAno(a => a + 1); }
      }
      // Escape = Fechar modais; se não houver nada aberto, volta ao Resumo (início)
      if (e.key === 'Escape') {
        const algoAberto = document.querySelector('.fixed.inset-0, [role="menu"], [role="dialog"]');
        setShowSearch(false);
        setShowAlerts(false);
        setShowImportCSV(false);
        setShowShortcuts(false);
        if (!algoAberto) { setTab('resumo'); window.scrollTo({ top: 0, behavior: 'smooth' }); }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [mes, ano]);
  
  const mesKey = `${ano}-${meses.indexOf(mes)+1}`;
  
  // Verificar se é o mês/ano atual
