  useEffect(() => {
    if (!remoto || !dataLoaded) return;
    const rem = { g: remoto.g || {}, m: remoto.m || {} };
    let base = null; try { base = lastSavedDataRef.current ? JSON.parse(lastSavedDataRef.current) : null; } catch (e) { base = null; }
    const junto = base && !isSavingRef.current ? juntarVersoes(base, { g: gRef.current, m: mRef.current }, rem) : null;
    if (junto) {
      // O que está agora no servidor passa a ser a base; o que mudaste aqui (noutras coisas) é gravado por cima dessa versão
      lastSavedDataRef.current = jsonEstavel(rem);
      adotarVersao(remoto.updatedAt);
      setG(junto.g); setM(junto.m);
    } else { conflitoRef.current = true; setConflito(true); }
  }, [remoto]); // eslint-disable-line react-hooks/exhaustive-deps
  const gravarPorCima = async () => {
    conflitoRef.current = false; setConflito(false);
    try { await onSaveData({ g: gRef.current, m: mRef.current }, { forcar: true }); lastSavedDataRef.current = jsonEstavel({ g: gRef.current, m: mRef.current }); pendingChangesRef.current = false; erroGravarRef.current = null; setErroGravar(null); showToast('Gravado — a versão deste ecrã ficou na cloud'); }
    catch (e) { const txt = String((e && e.message) || e); erroGravarRef.current = txt; setErroGravar(txt); }
  };

  useEffect(() => {
    if (!dataLoaded) return;
    
    if (isFirstLoadRef.current) {
      isFirstLoadRef.current = false;
      lastSavedDataRef.current = jsonEstavel({ g: G, m: M });
      return;
    }
    
    pendingChangesRef.current = true;
    
    if (saveTimeoutRef.current) {
      clearTimeout(saveTimeoutRef.current);
    }
    
    // 2 segundos de inatividade antes de guardar (reduzido de 10s: quanto
    // menor a espera, menor a hipótese de fechar a app antes de gravar).
    saveTimeoutRef.current = setTimeout(flushSave, 2000);
    
    return () => {
      if (saveTimeoutRef.current) clearTimeout(saveTimeoutRef.current);
    };
  }, [G, M, dataLoaded, flushSave]);

  // Gravar de imediato ao sair/minimizar a app ou bloquear o ecrã — sem isto,
  // alterações feitas nos últimos 10s (ex: marcar checks de transferências e
  // fechar logo a seguir) perdiam-se porque o temporizador nunca chegava a disparar.
  useEffect(() => {
    if (!dataLoaded) return;
    const handleVisibility = () => {
      if (document.visibilityState === 'hidden' && pendingChangesRef.current) flushSave();
    };
    const handlePageHide = () => {
      if (pendingChangesRef.current) flushSave();
    };
    document.addEventListener('visibilitychange', handleVisibility);
    window.addEventListener('pagehide', handlePageHide);
    return () => {
      document.removeEventListener('visibilitychange', handleVisibility);
      window.removeEventListener('pagehide', handlePageHide);
    };
  }, [dataLoaded, flushSave]);

 // Função para obter o mês anterior
 const getMesAnteriorKey = (currentKey) => {
 const [a, m] = currentKey.split('-').map(Number);
 if (m === 1) return `${a-1}-12`;
 return `${a}-${m-1}`;
 };

 // Obter portfolio do mês atual, ou copiar do mês anterior se não existir
 const getPortfolioParaMes = useCallback((key) => {
   // Se já tem portfolio para este mês, retornar
   if (patTemPortfolio(M[key]?.portfolio)) {
     return M[key].portfolio;
   }
   
   // Procurar no mês anterior para copiar estrutura E valores
   let checkKey = getMesAnteriorKey(key);
   let tentativas = 12; // máximo 12 meses para trás
   while (tentativas > 0) {
     if (patTemPortfolio(M[checkKey]?.portfolio)) {
       // Copiar portfolio do mês anterior com novos IDs
       return M[checkKey].portfolio.map(p => ({
         ...p,
         id: Date.now() + Math.random() * 1000 // Novo ID único
       }));
     }
     checkKey = getMesAnteriorKey(checkKey);
     tentativas--;
   }
   
   // Se não encontrar, usar default
   return defM.portfolio;
 }, [M]);

