 const getHist = useCallback(() => {
 const h = [];
 const nf = idsNaoFaturacao(G.clientes); // reembolsos e afins não são faturação
 Object.keys(M).forEach(k => {
 const [a,m] = k.split('-');
 const d = M[k];
 const c = (d.regCom || []).reduce((acc,r)=>acc+(nf.has(String(r.cid))?0:(Number(r.val)||0)),0);
 const s = (d.regSem || []).reduce((acc,r)=>acc+(nf.has(String(r.cid))?0:(Number(r.val)||0)),0);
 if(c>0||s>0) h.push({k,ano:+a,mes:+m,nome:meses[+m-1],com:c,sem:s,tot:c+s});
 });
 return h.sort((a,b)=>a.ano===b.ano?a.mes-b.mes:a.ano-b.ano);
 }, [M, G.clientes]);

 const catCoresInv = {'ETF':'#3b82f6','PPR':'#f59e0b','P2P':'#ec4899','CRIPTO':'#14b8a6','FE':'#10b981','CREDITO':'#ef4444'};

 // UI Components

  const modalBg = theme === 'light' ? 'bg-white border-slate-200 shadow-xl' : 'bg-slate-800 border-slate-700';
  // Select memoizado: mantém a MESMA identidade entre renders (só muda com o tema).
  // Sem isto, era recriado a cada render e o React desmontava/remontava todos os
  // dropdowns e campos à volta, fazendo-os "reiniciar" enquanto se escrevia.
  const Select = useMemo(() => ({children, className = '', ...props}) => <select className={`${theme === 'light' ? 'bg-slate-100 border-slate-300 text-slate-900' : 'bg-slate-700/50 border-slate-600 text-white'} border rounded-xl px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/50 appearance-none cursor-pointer smooth-colors ${className}`} {...props}>{children}</select>, [theme]);

  // Custom Color Picker (drag-friendly, stays open)
  const ColorPicker = ({value, onChange, className = ''}) => {
    const [cpOpen, setCpOpen] = useState(false);
    const [hsv, setHsv] = useState({h:0,s:1,v:1});
    const gradRef = useRef(null);
    const hueRef = useRef(null);
    const dragType = useRef(null);
    const popRef = useRef(null);
    const hsvRef = useRef(hsv);
    hsvRef.current = hsv;
    function hex2hsv(hex) {
      let r=0,g=0,b=0; if(!hex)hex='#3b82f6';
      if(hex.length===4){r=parseInt(hex[1]+hex[1],16);g=parseInt(hex[2]+hex[2],16);b=parseInt(hex[3]+hex[3],16);}
      else if(hex.length===7){r=parseInt(hex.slice(1,3),16);g=parseInt(hex.slice(3,5),16);b=parseInt(hex.slice(5,7),16);}
      r/=255;g/=255;b/=255;
      const mx=Math.max(r,g,b),mn=Math.min(r,g,b),d=mx-mn;
      let h=0,s2=mx===0?0:d/mx,v=mx;
      if(d!==0){if(mx===r)h=((g-b)/d+(g<b?6:0))/6;else if(mx===g)h=((b-r)/d+2)/6;else h=((r-g)/d+4)/6;}
      return {h,s:s2,v};
    }
    function hsv2hex(h,s2,v) {
      let r,g,b;const i=Math.floor(h*6),ff=h*6-i,p=v*(1-s2),q=v*(1-ff*s2),t=v*(1-(1-ff)*s2);
      switch(i%6){case 0:r=v;g=t;b=p;break;case 1:r=q;g=v;b=p;break;case 2:r=p;g=v;b=t;break;case 3:r=p;g=q;b=v;break;case 4:r=t;g=p;b=v;break;case 5:r=v;g=p;b=q;break;}
      const toH=n=>{const x=Math.round(n*255).toString(16);return x.length===1?"0"+x:x;};
      return "#"+toH(r)+toH(g)+toH(b);
    }
    const curHex = hsv2hex(hsv.h, hsv.s, hsv.v);
    useEffect(() => { if (cpOpen) setHsv(hex2hsv(value || '#3b82f6')); }, [cpOpen]);
    useEffect(() => {
      if (!cpOpen) return;
      const onMove = (e) => {
        if (!dragType.current) return;
        if (e.cancelable) e.preventDefault();
        if (dragType.current === 'grad') {
          const rect = gradRef.current?.getBoundingClientRect(); if (!rect) return;
          const cx = e.touches ? e.touches[0].clientX : e.clientX;
          const cy = e.touches ? e.touches[0].clientY : e.clientY;
          const x = Math.max(0, Math.min(1, (cx - rect.left) / rect.width));
          const y = Math.max(0, Math.min(1, (cy - rect.top) / rect.height));
          const nv = {...hsvRef.current, s: x, v: 1 - y};
          setHsv(nv); hsvRef.current = nv; onChange?.(hsv2hex(nv.h, nv.s, nv.v));
        } else if (dragType.current === 'hue') {
          const rect = hueRef.current?.getBoundingClientRect(); if (!rect) return;
          const cx = e.touches ? e.touches[0].clientX : e.clientX;
          const x = Math.max(0, Math.min(1, (cx - rect.left) / rect.width));
          const nv = {...hsvRef.current, h: x};
          setHsv(nv); hsvRef.current = nv; onChange?.(hsv2hex(nv.h, nv.s, nv.v));
        }
      };
      const onUp = () => { dragType.current = null; };
      const onOutside = (e) => {
        if (dragType.current) return;
        if (popRef.current && !popRef.current.contains(e.target)) setCpOpen(false);
      };
      window.addEventListener('mousemove', onMove);
      window.addEventListener('mouseup', onUp);
      window.addEventListener('touchmove', onMove, {passive: false});
      window.addEventListener('touchend', onUp);
      const tm = setTimeout(() => document.addEventListener('mousedown', onOutside), 100);
      return () => {
        window.removeEventListener('mousemove', onMove);
        window.removeEventListener('mouseup', onUp);
        window.removeEventListener('touchmove', onMove);
        window.removeEventListener('touchend', onUp);
        document.removeEventListener('mousedown', onOutside);
        clearTimeout(tm);
      };
    }, [cpOpen]);
    const startGrad = (e) => {
      e.stopPropagation(); dragType.current = 'grad';
      const rect = gradRef.current?.getBoundingClientRect(); if (!rect) return;
      const cx = e.touches ? e.touches[0].clientX : e.clientX;
      const cy = e.touches ? e.touches[0].clientY : e.clientY;
      const x = Math.max(0, Math.min(1, (cx - rect.left) / rect.width));
      const y = Math.max(0, Math.min(1, (cy - rect.top) / rect.height));
      const nv = {...hsvRef.current, s: x, v: 1 - y};
      setHsv(nv); hsvRef.current = nv; onChange?.(hsv2hex(nv.h, nv.s, nv.v));
    };
    const startHue = (e) => {
      e.stopPropagation(); dragType.current = 'hue';
      const rect = hueRef.current?.getBoundingClientRect(); if (!rect) return;
      const cx = e.touches ? e.touches[0].clientX : e.clientX;
      const x = Math.max(0, Math.min(1, (cx - rect.left) / rect.width));
      const nv = {...hsvRef.current, h: x};
      setHsv(nv); hsvRef.current = nv; onChange?.(hsv2hex(nv.h, nv.s, nv.v));
    };
    const presets = ["#ef4444","#f97316","#f59e0b","#22c55e","#10b981","#06b6d4","#3b82f6","#6366f1","#8b5cf6","#a855f7","#ec4899","#78716c"];
    return (
      <div className={"relative inline-block " + className}>
        <button type="button" onClick={(e) => { e.stopPropagation(); setCpOpen(!cpOpen); }}
          className="w-7 h-7 rounded-lg border-2 border-slate-600 cursor-pointer flex-shrink-0 hover:scale-110 transition-transform"
          style={{backgroundColor: value || '#3b82f6'}} />
        {cpOpen && (
          <div ref={popRef}
            className={"absolute z-[200] mt-1 right-0 p-3 rounded-xl shadow-2xl border " + (theme === "light" ? "bg-white border-slate-200" : "bg-slate-800 border-slate-600")}
            style={{width: 240}} onClick={e => e.stopPropagation()} onMouseDown={e => e.stopPropagation()}>
            <div ref={gradRef} className="relative w-full rounded-lg overflow-hidden cursor-crosshair select-none"
              style={{height: 160, background: "linear-gradient(to bottom, transparent, #000), linear-gradient(to right, #fff, " + hsv2hex(hsv.h, 1, 1) + ")"}}
              onMouseDown={startGrad} onTouchStart={startGrad}>
              <div className="absolute w-5 h-5 rounded-full border-2 border-white pointer-events-none"
                style={{left: "calc(" + hsv.s * 100 + "% - 10px)", top: "calc(" + (1 - hsv.v) * 100 + "% - 10px)", backgroundColor: curHex, boxShadow: "0 0 0 1px rgba(0,0,0,0.3), 0 2px 8px rgba(0,0,0,0.3)"}}/>
            </div>
            <div ref={hueRef} className="relative w-full h-4 rounded-full mt-3 cursor-pointer select-none"
              style={{background: "linear-gradient(to right, #f00 0%, #ff0 17%, #0f0 33%, #0ff 50%, #00f 67%, #f0f 83%, #f00 100%)"}}
              onMouseDown={startHue} onTouchStart={startHue}>
              <div className="absolute w-5 h-5 rounded-full border-2 border-white pointer-events-none"
                style={{left: "calc(" + hsv.h * 100 + "% - 10px)", top: "-2px", backgroundColor: hsv2hex(hsv.h, 1, 1), boxShadow: "0 0 0 1px rgba(0,0,0,0.3), 0 2px 4px rgba(0,0,0,0.2)"}}/>
            </div>
            <div className="flex flex-wrap gap-1.5 mt-3">
              {presets.map(p => (
                <button key={p} type="button" className={"w-6 h-6 rounded-md border-2 hover:scale-125 transition-transform " + (p === curHex ? "border-white ring-1 ring-blue-400 scale-110" : "border-slate-600/50")}
                  style={{backgroundColor: p}} onClick={() => { const nv = hex2hsv(p); setHsv(nv); hsvRef.current = nv; onChange?.(p); }}/>
              ))}
            </div>
            <div className="flex items-center gap-2 mt-3">
              <div className="w-7 h-7 rounded-lg border border-slate-600 flex-shrink-0" style={{backgroundColor: curHex}}/>
              <input type="text" value={curHex}
                className={"flex-1 text-xs font-mono px-2 py-1.5 rounded-lg " + (theme === "light" ? "bg-slate-100 border border-slate-200" : "bg-slate-700 border border-slate-600")}
                onChange={e => { const v2 = e.target.value; if (/^#[0-9a-f]{6}$/i.test(v2)) { const nv = hex2hsv(v2); setHsv(nv); hsvRef.current = nv; onChange?.(v2); }}}/>
              <button type="button" onClick={() => setCpOpen(false)}
                className={"text-xs font-medium px-2.5 py-1.5 rounded-lg " + (theme === "light" ? "bg-blue-50 text-blue-600 hover:bg-blue-100" : "bg-blue-500/20 text-blue-400 hover:bg-blue-500/30")}>OK</button>
            </div>
          </div>
        )}
      </div>
    );
  };
  const inputClass = theme === 'light' 
    ? "bg-slate-100 border border-slate-300 rounded-xl px-3 py-2 text-sm text-slate-900 focus:outline-none focus:ring-2 focus:ring-blue-500/50"
    : "bg-slate-700/50 border border-slate-600 rounded-xl px-3 py-2 text-sm text-white focus:outline-none focus:ring-2 focus:ring-blue-500/50";
  // Variante compacta (menos altura) para as linhas de listas de despesas/investimentos
  // Gera um resumo em linguagem natural das despesas, para colar noutra app
  // (ex: Bilance) e ela montar os orçamentos a partir daí.
  const gerarTextoDespesas = () => {
    const eur = v => _fmtEUR.format(parseFloat(v) || 0);

    const ab = (despABanca || []).filter(d => (parseFloat(d.val) || 0) > 0);
    const pess = (despPess || []).filter(d => (parseFloat(d.val) || 0) > 0);

    // Mês seguinte ao que está selecionado
    const idxAtual = meses.indexOf(mes);
    const proxMes = meses[(idxAtual + 1) % 12];
    const proxAno = idxAtual === 11 ? ano + 1 : ano;

    // Contas associadas a cada tipo de despesa
    const CONTA_CASAL = 'ABanca';
    const CONTA_PESSOAL = 'Activo Bank';

    const soma = lista => lista.reduce((a, d) => a + (parseFloat(d.val) || 0), 0);
    const totAb = soma(ab);
    const totPess = soma(pess);

    // 2 orçamentos globais (um por conta) + 1 por cada despesa
    const nGerais = (ab.length ? 1 : 0) + (pess.length ? 1 : 0);
    const nTotal = nGerais + ab.length + pess.length;
    let i = 0;
    const linha = (d, conta) => {
      i++;
      return `${i}. ${d.desc || 'Sem descrição'} — ${eur(d.val)} por mês — categoria: ${mapearCategoriaBilance(d.desc, migrateCat(d.cat))} — conta: ${conta}`;
    };

    const linhas = [];
    linhas.push(`Cria os meus orçamentos mensais para ${proxMes} de ${proxAno}.`);
    linhas.push('');
    linhas.push(`INSTRUÇÕES: cria um orçamento separado e individual para CADA uma das ${nTotal} linhas listadas abaixo — ou seja, ${nTotal} orçamentos no total, um por linha.`);
    linhas.push('Não agregues, não somes e não agrupes valores. Cada linha corresponde a um orçamento próprio, com o seu valor mensal, a sua categoria e a sua conta.');
    linhas.push('Usa o valor indicado em cada linha na totalidade, sem aplicar percentagens nem divisões.');
    linhas.push('As categorias já correspondem às tuas (grupo > subcategoria); usa-as exatamente como estão escritas.');
    linhas.push('');

    if (nGerais) {
      linhas.push(`ORÇAMENTOS GLOBAIS POR CONTA (${nGerais} ${nGerais === 1 ? 'orçamento' : 'orçamentos'}) — servem para ver o total gasto em cada conta, e por isso abrangem todas as categorias:`);
      if (ab.length) {
        i++;
        linhas.push(`${i}. Total ${CONTA_CASAL} — ${eur(totAb)} por mês — categoria: todas as categorias — conta: ${CONTA_CASAL}`);
      }
      if (pess.length) {
        i++;
        linhas.push(`${i}. Total ${CONTA_PESSOAL} — ${eur(totPess)} por mês — categoria: todas as categorias — conta: ${CONTA_PESSOAL}`);
      }
      linhas.push('Nota: estes dois orçamentos globais convivem com os orçamentos detalhados que se seguem — os detalhados são as despesas que compõem estes totais, não orçamentos adicionais a somar.');
      linhas.push('');
    }

    if (ab.length) {
      linhas.push(`ORÇAMENTOS A CRIAR NA CONTA ${CONTA_CASAL.toUpperCase()} (despesas do casal, ${ab.length} orçamentos):`);
      ab.forEach(d => linhas.push(linha(d, CONTA_CASAL)));
      linhas.push('');
    }

    if (pess.length) {
      linhas.push(`ORÇAMENTOS A CRIAR NA CONTA ${CONTA_PESSOAL.toUpperCase()} (despesas pessoais, ${pess.length} orçamentos):`);
      pess.forEach(d => linhas.push(linha(d, CONTA_PESSOAL)));
      linhas.push('');
    }

    linhas.push(`Confirma no fim que criaste os ${nTotal} orçamentos, um por cada linha acima.`);

    setTextoCopiado(false);
    setTextoBilance(linhas.join('\n'));
  };

  const copiarTextoBilance = async () => {
    try {
      await navigator.clipboard.writeText(textoBilance || '');
      setTextoCopiado(true);
      setTimeout(() => setTextoCopiado(false), 2000);
    } catch (e) {
      console.warn('Cópia falhou', e);
    }
  };

  const denseInputClass = theme === 'light'
    ? "bg-slate-100 border border-slate-300 rounded-lg px-2.5 py-1 text-sm text-slate-900 focus:outline-none focus:ring-2 focus:ring-blue-500/50"
    : "bg-slate-700/50 border border-slate-600 rounded-lg px-2.5 py-1 text-sm text-white focus:outline-none focus:ring-2 focus:ring-blue-500/50";
  
  // Classes auxiliares para tema
  const cardBg = theme === 'light' ? 'bg-slate-100' : 'bg-slate-700/30';
  const cardBgHover = theme === 'light' ? 'bg-slate-100 hover:bg-slate-200' : 'bg-slate-700/30 hover:bg-slate-700/50';
  const textMuted = theme === 'light' ? 'text-slate-600' : 'text-slate-400';

  // Componente genérico de Layout Editor para qualquer tab
  const LayoutEditor = ({ tabName, widgetDefs, currentLayout, onUpdateLayout, onReset }) => {
    const allWidgetIds = Object.keys(widgetDefs);
    const validLayout = currentLayout.filter(id => allWidgetIds.includes(id));
    const missingWidgets = allWidgetIds.filter(id => !validLayout.includes(id));
    const fullLayout = [...validLayout, ...missingWidgets];
    
    const moveWidget = (widgetId, direction) => {
      const idx = fullLayout.indexOf(widgetId);
      if (direction === 'up' && idx > 0) {
        const newLayout = [...fullLayout];
        [newLayout[idx], newLayout[idx - 1]] = [newLayout[idx - 1], newLayout[idx]];
        onUpdateLayout(newLayout);
      } else if (direction === 'down' && idx < fullLayout.length - 1) {
        const newLayout = [...fullLayout];
        [newLayout[idx], newLayout[idx + 1]] = [newLayout[idx + 1], newLayout[idx]];
        onUpdateLayout(newLayout);
      }
    };
    
    const tabNames = {
      resumo: 'Dashboard',
      receitas: 'Receitas',
      abanca: 'Despesas Casal',
      pessoais: 'Despesas Pessoais',
      invest: 'Alocação',
      portfolio: 'Portfolio'
    };
    
    return (
      <Card className="mb-6 border-purple-500/50 bg-purple-500/5">
        <div className="flex justify-between items-center mb-4">
          <h3 className={`font-semibold ${theme === 'light' ? 'text-purple-600' : 'text-purple-300'}`}><Ico e="🎨"/>Personalizar {tabNames[tabName] || tabName}</h3>
          <div className="flex gap-2">
            <button onClick={onReset} className={`px-3 py-1 text-xs rounded-lg ${theme === 'light' ? 'bg-slate-200 hover:bg-slate-300 text-slate-700' : 'bg-slate-700 hover:bg-slate-600 text-slate-300'}`}>Reset</button>
            <button onClick={() => setShowLayoutEditor(false)} className="px-3 py-1 text-xs bg-purple-500 hover:bg-purple-600 text-white rounded-lg">✓ Concluir</button>
          </div>
        </div>
        <p className={`text-xs mb-3 ${textMuted}`}>Use as setas para reordenar os widgets:</p>
        <div className="space-y-2">
          {fullLayout.map((widgetId, idx) => (
            <div key={widgetId} className={`flex items-center gap-3 p-2 rounded-lg ${cardBg}`}>
              <div className="flex flex-col gap-0.5">
                <button onClick={() => moveWidget(widgetId, 'up')} disabled={idx === 0} className={`px-1.5 py-0.5 text-xs rounded ${idx === 0 ? 'text-slate-500 cursor-not-allowed' : theme === 'light' ? 'hover:bg-slate-300 text-slate-600' : 'hover:bg-slate-600 text-slate-300'}`}>▲</button>
                <button onClick={() => moveWidget(widgetId, 'down')} disabled={idx === fullLayout.length - 1} className={`px-1.5 py-0.5 text-xs rounded ${idx === fullLayout.length - 1 ? 'text-slate-500 cursor-not-allowed' : theme === 'light' ? 'hover:bg-slate-300 text-slate-600' : 'hover:bg-slate-600 text-slate-300'}`}>▼</button>
              </div>
              <span className="text-sm font-medium flex-1">{widgetDefs[widgetId]?.name || widgetId}</span>
              <span className={`text-xs ${textMuted}`}>{widgetDefs[widgetId]?.desc}</span>
            </div>
          ))}
        </div>
      </Card>
    );
  };

 // Mês atual do sistema (para cálculos)
 const mesAtualSistemaNum = meses.indexOf(mesAtualSistema) + 1;
 
 // Mês relevante para o ano selecionado
 // - Ano passado: 12 (ano completo)
 // - Ano atual: mês atual do sistema
 // - Ano futuro: mês selecionado (ou 0 se for Janeiro)
 const mesAtualNum = ano < anoAtualSistema 
   ? 12 
   : ano > anoAtualSistema 
     ? meses.indexOf(mes) + 1
     : mesAtualSistemaNum;
 
 // Mês selecionado na UI
 const mesSelecionadoIdx = meses.indexOf(mes) + 1;
 
 // Progresso esperado baseado no contexto
 const progressoEsperado = ano < anoAtualSistema 
   ? 1 // 100% - ano completo
   : ano > anoAtualSistema 
     ? mesSelecionadoIdx / 12 // progresso até ao mês selecionado (ano futuro)
     : Math.min(mesSelecionadoIdx, mesAtualSistemaNum) / 12; // menor entre mês selecionado e mês atual

 // Calcular totais anuais para metas
 // Faturado por cliente, por ano e mês (para a ficha de cliente no Trabalho)
 const faturadoClientes = useMemo(() => {
   const out = {};
   Object.entries(M || {}).forEach(([k, md]) => {
     const [a, m] = k.split('-').map(Number);
     if (!a || !m || m > 12 || !md) return;
     [...(md.regCom || []), ...(md.regSem || [])].forEach(r => {
       const o = (out[r.cid] = out[r.cid] || {});
       const y = (o[a] = o[a] || Array(12).fill(0));
       y[m - 1] += Number(r.val) || 0;
     });
   });
   return out;
 }, [M]);

 const calcularTotaisAnuais = useCallback(() => {
   let receitasAnuais = 0;
   let investimentosAnuais = 0;
   const receitasPorCliente = {};
   
   // Inicializar clientes
   clientes.forEach(c => { receitasPorCliente[c.id] = { nome: c.nome, cor: c.cor, total: 0 }; });
   
   // Determinar até que mês contar
   // - Ano passado: todos os 12 meses
   // - Ano atual: até ao mês atual do sistema
   // - Ano futuro: até ao mês selecionado (ou 0 se ainda não começou)
   const hoje = new Date();
   const mesAtualReal = hoje.getMonth() + 1; // 1-12
   const anoAtualReal = hoje.getFullYear();
   
   let mesesAContar;
   if (ano < anoAtualReal) {
     mesesAContar = 12; // Ano passado - contar tudo
   } else if (ano === anoAtualReal) {
     mesesAContar = mesAtualReal; // Ano atual - só até ao mês atual
   } else {
     mesesAContar = 0; // Ano futuro - ainda não há dados reais
   }
   
   const nf = idsNaoFaturacao(clientes); // reembolsos e afins não são faturação
   let liquidoAnual = 0; // o que ficou depois da reserva para impostos (para a taxa de poupança)
   for (let i = 1; i <= mesesAContar; i++) {
     const k = `${ano}-${i}`;
     const mesData = M[k] || {};
     const fatMes = faturacaoDoMes(mesData, nf);
     receitasAnuais += fatMes;
     liquidoAnual += fatMes - reservaMes(mesData);
     
     // Receitas por cliente
     mesData.regCom?.forEach(r => { if (receitasPorCliente[r.cid] && !nf.has(String(r.cid))) receitasPorCliente[r.cid].total += Number(r.val) || 0; });
     mesData.regSem?.forEach(r => { if (receitasPorCliente[r.cid] && !nf.has(String(r.cid))) receitasPorCliente[r.cid].total += Number(r.val) || 0; });
     
     // Investimentos do mês (exceto CREDITO)
     const invMes = mesData.inv?.filter(inv => inv.cat !== 'CREDITO').reduce((a, inv) => a + inv.val, 0) || 0;
     investimentosAnuais += invMes;
   }
   
   // Amortização real baseada no histórico de dívida
   // Usar novo sistema G.creditos se disponível, senão fallback para G.credito
   const creditosAtivos = G.creditos?.filter(c => c.estado === 'ativo') || [];
   const creditoParaCalculo = creditosAtivos.length > 0 ? creditosAtivos[0] : G.credito;
   
   const historico = creditoParaCalculo?.historico || [];
   const anoStr = ano.toString();
   const anoAnteriorStr = (ano - 1).toString();
   
   // Ordenar histórico por data
   const historicoOrdenado = [...historico].sort((a, b) => a.date.localeCompare(b.date));
   
   // Encontrar o registo mais próximo do início do ano (dezembro do ano anterior ou antes)
   const registosAteInicioAno = historicoOrdenado.filter(h => h.date <= `${anoAnteriorStr}-12`);
   const registosDoAno = historicoOrdenado.filter(h => h.date.startsWith(anoStr));
   
   // Dívida no início do ano
   let dividaInicio = creditoParaCalculo?.montanteInicial || 328500;
   
   if (registosAteInicioAno.length > 0) {
     // Usar o último registo até dezembro do ano anterior
     dividaInicio = registosAteInicioAno[registosAteInicioAno.length - 1].divida;
   }
   
   // Para anos futuros, não há amortização ainda
   let amortizacaoAnual = 0;
   
   if (ano < anoAtualReal) {
     // Ano passado - usar dívida atual como referência final
     const dividaFimAno = creditoParaCalculo?.dividaAtual || dividaInicio;
     amortizacaoAnual = Math.max(0, dividaInicio - dividaFimAno);
   } else if (ano === anoAtualReal) {
     // Ano atual - calcular apenas com base em registos do histórico DESTE ano
     // Não usar dividaAtual diretamente porque pode estar desatualizada ou incluir dados futuros
     
     if (registosDoAno.length > 0) {
       // Usar o último registo do ano atual
       const ultimoRegistoAno = registosDoAno[registosDoAno.length - 1];
       amortizacaoAnual = Math.max(0, dividaInicio - ultimoRegistoAno.divida);
     } else {
       // Não há registos este ano ainda - verificar se há meses passados
       if (mesesAContar > 0 && creditoParaCalculo?.prestacao) {
         // Estimar amortização baseada na prestação
         const taxaMensal = (creditoParaCalculo?.taxaJuro ?? 2) / 100 / 12;
         const jurosMensais = dividaInicio * taxaMensal;
         const amortMensal = Math.max(0, creditoParaCalculo.prestacao - jurosMensais);
         amortizacaoAnual = amortMensal * mesesAContar;
       }
       // Se mesesAContar = 0 (ainda em Janeiro e não passou nenhum mês completo), fica 0
     }
   }
   // Para ano > anoAtualReal, amortizacaoAnual fica 0
   
   // Dívida atual para mostrar no UI
   const dividaAtualCalc = registosDoAno.length > 0 
     ? registosDoAno[registosDoAno.length - 1].divida 
     : (creditoParaCalculo?.dividaAtual || dividaInicio);
   
   // Investimentos em portfolio com categoria CREDITO (amortizações extra manuais)
   // Só contar se for ano atual ou passado
   let amortizacaoExtra = 0;
   if (ano <= anoAtualReal) {
     for (let i = 1; i <= mesesAContar; i++) {
       const k = `${ano}-${i}`;
       const portfolioMes = M[k]?.portfolio || [];
       amortizacaoExtra += portfolioMes.filter(p => p.cat === 'CREDITO').reduce((a, p) => a + p.val, 0);
     }
   }
   
   // Total = amortização calculada + extras manuais
   const amortizacaoTotal = amortizacaoAnual + amortizacaoExtra;
   
   return { 
     receitasAnuais, 
     liquidoAnual,
     amortAnual: amortizacaoTotal,
     amortizacaoAnual: amortizacaoTotal,
     amortizacaoBase: amortizacaoAnual,
     amortizacaoExtra,
     investAnual: investimentosAnuais,
     investimentosAnuais,
     receitasPorCliente,
     dividaInicio,
     dividaAtual: dividaAtualCalc
   };
 }, [ano, M, mesKey, clientes, G.credito, mesAtualNum, taxa]); // eslint-disable-line react-hooks/exhaustive-deps

 const totaisAnuais = calcularTotaisAnuais();

 // RESUMO

 const calcPrevisaoImpostos = () => impCalc(G, M);
 const previsaoImpostos = (() => { try { return calcPrevisaoImpostos(); } catch(e) { console.error('calcPrevisaoImpostos error:', e); return { totalIliquido: 0, totalPT: 0, totalUE: 0, totalForaUE: 0, ssAnual: 0, ssMensal: 0, ssProximoMes: 0, rendimentoRelevanteSS: 0, receitasTrimestreDeclarado: 0, nomeMesesDeclarados: '', anoMesesDeclarados: anoAtualSistema, ssBaseIncidenciaMensal: 0, ssProximoTrimestre: 0, nomeMesesProximos: '', trimestrePagamento: '', ivaAPagar: 0, ivaTrimestral: 0, ivaTrimestreAtual: 0, trimestreAtual: 1, proximoTrimestre: 2, anoProximoTrimestre: anoAtualSistema, ivaTrimestreAnterior: 0, trimestreAnterior: 4, anoTrimestreAnterior: anoAtualSistema - 1, chaveIvaAnterior: '', ivaPagoAnterior: null, dataLimiteIva: new Date(), diasParaIva: 0, irsEstimado: 0, irsRetencoes: 0, irsAPagarReceber: 0, irsTaxaEfetiva: 0, totalImpostos: 0, ssEste: { mes: 0, base: 0, rec: 0, formula: 0, nomeBase: '', anoBase: anoAtualSistema, valor: 0 }, ssProx: { mes: 0, base: 0, rec: 0, formula: 0, nomeBase: '', anoBase: anoAtualSistema, valor: 0 }, ssDepois: { mes: 0, base: 0, rec: 0, formula: 0, nomeBase: '', anoBase: anoAtualSistema, valor: 0, incompleto: true }, irsCfg: { ...IRS_CFG_PADRAO }, anoTrimestreAtual: anoAtualSistema, mesPagarIvaAtual: '', fatorSS: 1, fatorIVA: 1, paresIVA: 0, porConta: 0, taxaReservaSugerida: null, calibracao: { ativa: false, anosBase: [], SS: null, IVA: null, IRS: null } }; } })();
 // ══ Eventos do calendário financeiro de um mês (y, m 1-12) ══
 const eventosCalendario = (y, m) => {
   const idx = y * 12 + m - 1, hojeD = new Date(), hIdx = hojeD.getFullYear() * 12 + hojeD.getMonth(), hDia = hojeD.getDate();
   const conc = G.tarefasConcluidas || {};
   const pi = previsaoImpostos || {};
   const nDias = new Date(y, m, 0).getDate();
   const est = (feito, d) => feito ? 'ok' : (idx < hIdx || (idx === hIdx && d < hDia)) ? 'atrasado' : 'futuro';
   const pagos = tipo => (G.impostosPagos || []).filter(p => p.tipo === tipo && patNum(p.valor) > 0 && String(p.data || '').startsWith(`${y}-${String(m).padStart(2, '0')}`));
   const irImp = () => { setTab('resumo'); setTimeout(() => document.getElementById('cartao-impostos')?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 80); };
   const L = [];
   // Prestação da casa (dia 1)
   const prest = patNum((creditoAtual || {}).prestacao);
   if (prest > 0) L.push({ id: 'prest', dia: 1, cat: 'Casa', titulo: 'Prestação da casa (sai da ABanca)', curto: 'Prestação', valor: prest, estado: idx < hIdx || (idx === hIdx && hDia > 1) ? 'ok' : 'futuro' });
   // Tarefas da Agenda
   (G.tarefas || []).filter(t => t && t.ativo !== false && (t.freq === 'mensal' || ((t.freq === 'anual' || t.freq === 'trimestral') && Array.isArray(t.meses) && t.meses.includes(m)))).forEach(t => {
     const d = Math.min(nDias, Math.max(1, parseInt(t.dia) || 1));
     const chave = `${y}-${m}-${t.id}`;
     let feito = conc[chave] === true, valor = 0, nota = '';
     const pagar = /pagar|pagamento/i.test(t.desc || '');
     if (t.cat === 'SS' && pagar && pi.ssPara) {
       const s = pi.ssPara(idx); valor = s.valor; nota = `Contribuição de ${meses[(idx - 1 + 12) % 12]} · base ${s.nomeBase}`;
       if (pagos('SS').length) feito = true;
     }
     if (t.cat === 'IVA' && pagar && pi.ivaPag) {
       const v = pi.ivaPag(idx); valor = v.valor; nota = `IVA do ${v.t}.º trimestre de ${v.ano}${v.valor < 0.5 ? ' · sem IVA a pagar, só declarar' : ''}`;
       if (v.pago) feito = true;
     }
     let lista = null;
     if (t.cat === 'Contab' || /enviar faturas/i.test(t.desc || '')) {
       const fim = idx - 2, ini = fim - 2, mm = String(m).padStart(2, '0');
       nota = `Faturas de ${meses[((ini % 12) + 12) % 12]} a ${meses[((fim % 12) + 12) % 12]} de ${Math.floor(fim / 12)} · o contabilista declara até 20/${mm} e pagas até 25/${mm}`;
       lista = [
         'Os teus recibos verdes do trimestre — assinala os de clientes da UE (vão para a declaração recapitulativa)',
         'Faturas de despesas da atividade com o teu NIF e IVA português (equipamento, software, etc.) — o IVA é dedutível',
         'Faturas de serviços estrangeiros (Adobe, ferramentas de IA, subscrições) — autoliquidação do IVA',
         'Não envies despesas pessoais (supermercado, saúde, casa) — essas só contam no e-Fatura para o IRS',
       ];
     } else if (/e-?fatura/i.test(t.desc || '') && t.freq === 'mensal') {
       nota = `Confirma as faturas de ${meses[((idx - 1) % 12 + 12) % 12]}: marca as da atividade e classifica as pessoais (deduções do IRS)`;
     }
     L.push({ id: 't' + t.id, lista, dia: d, cat: t.cat || 'Rotina', titulo: t.desc, curto: t.cat && t.cat !== 'Transf' && t.cat !== 'Invest' ? `${t.cat}: ${String(t.desc).replace(/^(Pagar|Entregar)\s+/i, '')}` : t.desc, valor, nota, chave, estado: est(feito, d), ir: t.cat === 'SS' || t.cat === 'IVA' || t.cat === 'IRS' ? irImp : () => setTab('agenda') });
   });
   // Rotina: início do mês e preparar o seguinte
   const mk = patKey(idx), md = M[mk] || {};
   const temRec = ((md.regCom || []).length + (md.regSem || []).length) > 0;
   L.push({ id: 'r-inicio', dia: Math.min(3, nDias), cat: 'Rotina', titulo: 'Recibos, Alocação e transferências (quando os clientes pagarem)', curto: 'Recibos e alocação', estado: temRec ? 'ok' : est(false, 3), ir: () => { setAno(y); setMes(meses[m - 1]); setTab('resumo'); } });
   // (As entregas do Trabalho ficam só no Calendário de projetos, dentro do Trabalho)
   // Venda da casa: prazos do CPCV (separador Venda da Casa)
   vcPrazosCPCV({ ...VC_DEFAULT, ...(G.vendaCasa || {}) }, conc)
     .filter(p => p.data.getFullYear() === y && p.data.getMonth() + 1 === m)
     .forEach(p => L.push({ id: 'vc-' + p.id, dia: p.data.getDate(), cat: 'Venda', titulo: p.titulo, curto: p.curto, nota: p.nota, lista: p.lista || null, chave: p.chave, estado: p.estado, ir: () => setTab('vendacasa') }));
   const kp = patKey(idx + 1), tp = (M[kp] || {}).transf || {};
   const prepFeito = !!(tp.g_abanca || tp.g_adiant);
   L.push({ id: 'r-prep', dia: Math.min(20, nDias), cat: 'Rotina', titulo: `Preparar ${meses[m % 12]}: rever despesas e mandar a ABanca antes do dia 1`, curto: `Preparar ${meses[m % 12]}`, valor: guia.valAB, estado: prepFeito ? 'ok' : est(false, nDias), ir: () => { setAno(Math.floor((idx + 1) / 12)); setMes(meses[(idx + 1) % 12]); setTab('resumo'); setTimeout(() => document.getElementById('guia-transf')?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 80); } });
   return L.sort((a, b) => a.dia - b.dia);
 };
 // Tema no <html>: os ajustes de contraste (CSS_BASE) também chegam às janelas abertas por portal
