 <Select value={p.cat} onChange={e=>uM('portfolio',portfolio.map(x=>x.id===p.id?{...x,cat:e.target.value}:x))} className="flex-1 min-w-[80px] m-grow">{catsInv.map(c=><option key={c} value={c}>{c}</option>)}</Select>
