 // Gerar Relatório Anual
 const [showRelatorio, setShowRelatorio] = useState(false);
 
 const gerarRelatorioAnual = (anoRel) => {
   const h = getHist().filter(x => x.ano === anoRel);
   const totalReceitas = h.reduce((a, x) => a + x.tot, 0);
   const totalComTaxas = h.reduce((a, x) => a + x.com, 0);
   const totalSemTaxas = h.reduce((a, x) => a + x.sem, 0);
   const mediaMensal = h.length > 0 ? totalReceitas / h.length : 0;
   
   // Horas trabalhadas no ano
   let totalHoras = 0;
   const horasPorMes = [];
   Object.entries(M).forEach(([key, data]) => {
     const [a, m] = key.split('-').map(Number);
     if (a === anoRel && data.horasTrabalhadas > 0) {
       totalHoras += data.horasTrabalhadas;
       const receitaMes = (data.regCom || []).reduce((acc, r) => acc + r.val, 0) + 
                         (data.regSem || []).reduce((acc, r) => acc + r.val, 0);
       horasPorMes.push({
         mes: meses[m - 1],
         horas: data.horasTrabalhadas,
         receita: receitaMes,
         valorHora: receitaMes / data.horasTrabalhadas
       });
     }
   });
   const totalDias = totalHoras / 8;
   const valorHoraMedio = totalHoras > 0 ? totalReceitas / totalHoras : 0;
   const valorDiaMedio = totalDias > 0 ? totalReceitas / totalDias : 0;
   const mediaHorasMes = horasPorMes.length > 0 ? totalHoras / horasPorMes.length : 0;
   
   // Por cliente
   const porCliente = clientes.map(c => {
     let total = 0;
     Object.entries(M).forEach(([key, data]) => {
       const [a] = key.split('-').map(Number);
       if (a === anoRel) {
         total += (data.regCom || []).filter(r => r.cid === c.id).reduce((acc, r) => acc + r.val, 0);
         total += (data.regSem || []).filter(r => r.cid === c.id).reduce((acc, r) => acc + r.val, 0);
       }
     });
     return { ...c, total };
   }).filter(c => c.total > 0).sort((a, b) => b.total - a.total);
   
   // Investimentos do ano
   let totalInvestido = 0;
   Object.entries(M).forEach(([key, data]) => {
     const [a] = key.split('-').map(Number);
     if (a === anoRel) {
       totalInvestido += (data.inv || []).reduce((acc, i) => acc + i.val, 0);
     }
   });
   
   // Impostos estimados
   const impostoEstimado = Object.entries(M).filter(([k]) => Number(k.split('-')[0]) === anoRel).reduce((a, [, d]) => a + reservaMes(d), 0); // Com + Sem Taxas, como no ecrã
   
   // Dados de créditos
   const creditosData = G.creditos || [];
   const creditosAtivos = creditosData.filter(c => c.estado === 'ativo');
   const creditosLiquidadosAno = creditosData.filter(c => c.estado === 'liquidado' && c.dataLiquidacao?.startsWith(String(anoRel)));
   const totalDividaAtiva = creditosAtivos.reduce((acc, c) => acc + (c.dividaAtual || 0), 0);
   
   // Calcular amortização do ano para cada crédito
   const amortizacaoPorCredito = creditosData.map(c => {
     const hist = c.historico || [];
     const inicioAno = hist.find(h => h.date === `${anoRel-1}-12`)?.divida || c.montanteInicial;
     const fimAno = hist.find(h => h.date === `${anoRel}-12`)?.divida || c.dividaAtual;
     const amortizado = inicioAno - fimAno;
     return { ...c, amortizado: amortizado > 0 ? amortizado : 0, inicioAno, fimAno };
   }).filter(c => c.amortizado > 0);
   
   const totalAmortizadoAno = amortizacaoPorCredito.reduce((acc, c) => acc + c.amortizado, 0);
   
   return {
     ano: anoRel,
     totalReceitas,
     totalComTaxas,
     totalSemTaxas,
     mediaMensal,
     porCliente,
     totalInvestido,
     impostoEstimado,
     mesesComDados: h.length,
     melhorMes: h.length > 0 ? h.reduce((a, x) => x.tot > a.tot ? x : a, h[0]) : null,
     piorMes: h.filter(x => x.tot > 0).length > 0 ? h.filter(x => x.tot > 0).reduce((a, x) => x.tot < a.tot ? x : a, h[0]) : null,
     // Dados de horas
     totalHoras,
     totalDias,
     valorHoraMedio,
     valorDiaMedio,
     mediaHorasMes,
     horasPorMes,
     mesesComHoras: horasPorMes.length,
     // Dados de créditos
     creditosAtivos,
     creditosLiquidadosAno,
     totalDividaAtiva,
     amortizacaoPorCredito,
     totalAmortizadoAno
   };
 };
 
